/**
 * Contract tests for `scripts/agent-definitions-drift.mjs` (#1595).
 *
 * `agents/agents/{claude-code,gemini-cli}/harness-*.md` are generated by
 * `harness generate-agent-definitions` and say "Do not edit", but nothing
 * regenerated or checked them: they sat unchanged from 2026-06-07 while the
 * CLI moved on, 11 of 16 drifted per host and `harness-harness-pm.md` never
 * arrived. The doc gates skip generated trees by design, so it was invisible.
 * Same shape as #1249 (Gemini commands), same remedy.
 *
 * Two halves, as in gemini-commands-drift.test.ts:
 *   - a FAKE generator (handed over through `HARNESS_BIN`) pins the contract
 *     offline: clean, planted drift per host, stale and missing files,
 *     `--write`, and every abstention;
 *   - the REAL repo against the REAL generator, local-only (the TS engine CI
 *     job has no harness CLI). CI enforcement is the `validate` job step in
 *     `.github/workflows/harness-quality.yml`.
 */

import { spawnSync } from 'node:child_process';
import {
  chmodSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { runCapture } from './subprocess-testkit.js';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const SCRIPT = join(REPO_ROOT, 'scripts', 'agent-definitions-drift.mjs');
const REGEN = 'node scripts/agent-definitions-drift.mjs --write';
const HOSTS = ['claude-code', 'gemini-cli'];
const AGENTS = ['harness-alpha.md', 'harness-beta.md'];

/**
 * Stands in for `harness generate-agent-definitions --output <dir>`: one file
 * per agent per host under `<dir>/<host>/`, as the real CLI lays it out.
 * `FAKE_GEN` picks a failure mode.
 */
const FAKE_GENERATOR = `#!/usr/bin/env node
const fs = require('node:fs');
const path = require('node:path');
const argv = process.argv;
if (argv.includes('--version')) { console.log('13.0.0-fake'); process.exit(0); }
const mode = process.env.FAKE_GEN || 'ok';
if (mode === 'crash') { console.error('generator exploded'); process.exit(1); }
const out = argv[argv.indexOf('--output') + 1];
const hosts = argv[argv.indexOf('--platforms') + 1].split(',');
for (const host of hosts) {
  fs.mkdirSync(path.join(out, host), { recursive: true });
  if (mode === 'empty' || (mode === 'one-host' && host === 'gemini-cli')) continue;
  for (const name of ${JSON.stringify(AGENTS)}) {
    fs.writeFileSync(path.join(out, host, name), '# ' + host + ' ' + name + '\\n');
  }
}
`;

let root: string;
let generator: string;

beforeEach(() => {
  root = mkdtempSync(join(tmpdir(), 'agent-defs-drift-'));
  generator = join(root, 'fake-harness.cjs');
  writeFileSync(generator, FAKE_GENERATOR, 'utf-8');
  chmodSync(generator, 0o755);
});
afterEach(() => {
  rmSync(root, { recursive: true, force: true });
});

const committed = (host: string, name: string) =>
  join(root, 'agents', 'agents', host, name);

function writeAt(path: string, body: string): void {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, body, 'utf-8');
}

/** A repo whose committed definitions match what the fake emits. */
function inSyncRepo(): void {
  for (const host of HOSTS)
    for (const name of AGENTS)
      writeAt(committed(host, name), `# ${host} ${name}\n`);
}

function check(args: string[] = [], env: NodeJS.ProcessEnv = {}) {
  return runCapture('node', [SCRIPT, '--root', root, ...args], {
    env: { ...process.env, HARNESS_BIN: generator, ...env },
  });
}

describe('agent-definitions-drift — in sync', () => {
  it('exits 0 and states the denominator per host', () => {
    inSyncRepo();
    const r = check();
    expect(r.status, r.output).toBe(0);
    expect(r.output).toMatch(/4 of 4 agent definitions match/);
    expect(r.output).toMatch(/13\.0\.0-fake/);
  });
});

describe('agent-definitions-drift — drift is a failure', () => {
  it('a definition the CLI has since changed exits 1, naming the host', () => {
    inSyncRepo();
    writeAt(committed('gemini-cli', 'harness-beta.md'), '# old template\n');
    const r = check();
    expect(r.status, r.output).toBe(1);
    expect(r.output).toMatch(/changed: gemini-cli\/harness-beta\.md/);
    expect(r.output).toContain(REGEN);
  });

  it('an agent with no committed definition exits 1 (the harness-pm shape)', () => {
    inSyncRepo();
    rmSync(committed('claude-code', 'harness-alpha.md'));
    const r = check();
    expect(r.status, r.output).toBe(1);
    expect(r.output).toMatch(/missing: claude-code\/harness-alpha\.md/);
  });

  it('a committed definition the generator no longer emits exits 1', () => {
    inSyncRepo();
    writeAt(committed('claude-code', 'harness-retired.md'), '# gone\n');
    const r = check();
    expect(r.status, r.output).toBe(1);
    expect(r.output).toMatch(/stale: claude-code\/harness-retired\.md/);
  });

  it('--write regenerates both hosts, after which the check passes', () => {
    inSyncRepo();
    writeAt(committed('gemini-cli', 'harness-beta.md'), '# old template\n');
    writeAt(committed('claude-code', 'harness-retired.md'), '# gone\n');
    rmSync(committed('claude-code', 'harness-alpha.md'));
    expect(check(['--write']).status).toBe(0);
    expect(
      readdirSync(join(root, 'agents', 'agents', 'claude-code')).sort(),
    ).toEqual(AGENTS);
    expect(
      readFileSync(committed('gemini-cli', 'harness-beta.md'), 'utf-8'),
    ).toBe('# gemini-cli harness-beta.md\n');
    expect(check().status).toBe(0);
  });
});

describe('agent-definitions-drift — abstains (exit 3), never passes', () => {
  it('when the generator is not installed', () => {
    inSyncRepo();
    const r = check([], { HARNESS_BIN: join(root, 'no-such-harness') });
    expect(r.status, r.output).toBe(3);
    expect(r.output).toMatch(/ABSTAINED/);
    expect(r.output).not.toMatch(/match a fresh generation/);
  });

  it('when the generator exits non-zero', () => {
    inSyncRepo();
    const r = check([], { FAKE_GEN: 'crash' });
    expect(r.status, r.output).toBe(3);
    expect(r.output).toMatch(/generator exploded/);
  });

  it('when the generator emits zero definitions', () => {
    inSyncRepo();
    const r = check([], { FAKE_GEN: 'empty' });
    expect(r.status, r.output).toBe(3);
    expect(r.output).toMatch(/0 agent definitions/);
  });

  it('when one host comes back empty (a silent half-check is not a pass)', () => {
    inSyncRepo();
    const r = check([], { FAKE_GEN: 'one-host' });
    expect(r.status, r.output).toBe(3);
    expect(r.output).toMatch(/gemini-cli/);
  });

  it('--write never writes from an abstained generation', () => {
    inSyncRepo();
    const r = check(['--write'], { FAKE_GEN: 'empty' });
    expect(r.status).toBe(3);
    expect(
      readdirSync(join(root, 'agents', 'agents', 'gemini-cli')),
    ).toHaveLength(2);
  });
});

const hasHarness = !spawnSync('harness', ['--version']).error;

/**
 * The reproducing case for #1595: the committed trees against a fresh
 * generation by the real CLI. Red on main (11 changed + 1 missing per host),
 * green after the regeneration. Local-only: see the header.
 */
describe.runIf(hasHarness)('agent-definitions-drift — this repository', () => {
  it('the committed agent definitions match a fresh generation', () => {
    const r = runCapture('node', [SCRIPT], {
      env: { ...process.env, HARNESS_BIN: 'harness' },
    });
    expect(r.status, r.output).toBe(0);
  }, 60_000);
});
